def can_transform_to_equal(nums,k):
    def operations(target):
        incoming=1;used=0
        for value in nums[:-1]:
            if value*incoming!=target:incoming=-1;used+=1
            else:incoming=1
        return used if nums[-1]*incoming==target else 10**30
    return min(operations(1),operations(-1))<=k

